11	/**
12	 * Builds the {@link Owner} entity from the request body published by
13	 * {@link ValidateOwnerFields} (which is the single {@code @RequestBody} reader in the
14	 * {@code POST /api/owners} pipeline).
15	 *
16	 * <p>When the request omits a registration date it defaults to the server's current
17	 * date, so every created owner is persisted (and returned) with a registration date.
18	 */
19	public class BuildOwner {
20	
21	    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built) {
22	        Owner owner = ownerMapper.toOwner(request);
